package app

import (
	"bytes"
	"encoding/csv"
	"errors"
	"io"
	"math"
	"mime/multipart"
	"net/http"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"golang.org/x/text/encoding/korean"

	"github.com/xuri/excelize/v2"
)

const maxVisitorImportSize = 6 << 20

func (s *Server) previewVisitorImport(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxVisitorImportSize)
	if err := r.ParseMultipartForm(maxVisitorImportSize); err != nil {
		writeError(w, http.StatusBadRequest, "import_too_large", "CSV/XLSX 파일은 6MB 이하여야 합니다")
		return
	}
	if r.MultipartForm != nil {
		defer r.MultipartForm.RemoveAll()
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, http.StatusBadRequest, "file_required", "가져올 CSV 또는 XLSX 파일을 선택하세요")
		return
	}
	defer file.Close()

	rows, err := readVisitorImportRows(file, header)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_import", err.Error())
		return
	}
	visitors, warnings, err := visitorInputsFromRows(rows)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_import", err.Error())
		return
	}
	u, _ := userFrom(r)
	s.audit(r.Context(), u.ID, "visitor_import.preview", "visitor_import", "", clientIP(r), map[string]any{"filename": filepath.Base(header.Filename), "rows": len(visitors), "warnings": len(warnings)})
	writeJSON(w, http.StatusOK, map[string]any{"visitors": visitors, "warnings": warnings})
}

func readVisitorImportRows(file multipart.File, header *multipart.FileHeader) ([][]string, error) {
	ext := strings.ToLower(filepath.Ext(header.Filename))
	switch ext {
	case ".csv":
		data, err := io.ReadAll(file)
		if err != nil {
			return nil, errors.New("CSV 파일을 읽을 수 없습니다")
		}
		reader := csv.NewReader(bytes.NewReader(decodeSpreadsheetText(data)))
		reader.FieldsPerRecord = -1
		reader.LazyQuotes = true
		rows, err := reader.ReadAll()
		if err != nil {
			return nil, errors.New("CSV 형식을 읽을 수 없습니다")
		}
		return rows, nil
	case ".xlsx":
		book, err := excelize.OpenReader(file)
		if err != nil {
			return nil, errors.New("XLSX 형식을 읽을 수 없습니다")
		}
		defer book.Close()
		sheets := book.GetSheetList()
		if len(sheets) == 0 {
			return nil, errors.New("XLSX에 워크시트가 없습니다")
		}
		rows, err := book.GetRows(sheets[0])
		if err != nil {
			return nil, errors.New("XLSX 첫 번째 워크시트를 읽을 수 없습니다")
		}
		return rows, nil
	default:
		return nil, errors.New("지원 파일 형식은 .csv와 .xlsx입니다")
	}
}

// decodeSpreadsheetText normalises what Excel actually produces. Korean Windows
// saves "CSV (쉼표로 분리)" in CP949, not UTF-8, so a file exported from Excel
// arrived as mojibake and failed with "이름(name) 열이 필요합니다" even though the
// column was there. A UTF-8 byte-order mark is stripped for the same reason.
func decodeSpreadsheetText(data []byte) []byte {
	data = bytes.TrimPrefix(data, []byte{0xEF, 0xBB, 0xBF})
	if utf8.Valid(data) {
		return data
	}
	decoded, err := korean.EUCKR.NewDecoder().Bytes(data)
	if err != nil {
		return data
	}
	return decoded
}

// importHeaderAliases maps the column names people actually type, lower-cased
// with spaces, underscores and hyphens removed, onto the visitor fields.
var importHeaderAliases = map[string]string{
	"name": "name", "이름": "name", "방문자이름": "name", "성명": "name",
	"phone": "phone", "mobile": "phone", "휴대전화": "phone", "전화번호": "phone", "휴대폰": "phone", "연락처": "phone",
	"email": "email", "이메일": "email",
	"company": "company", "회사": "company", "회사명": "company",
	"title": "title", "직책": "title",
	"vehicle": "vehicle", "차량번호": "vehicle",
	"equipment": "equipment", "반입장비": "equipment",
	"consent": "consent", "개인정보동의": "consent", "동의": "consent",
	"locale": "locale", "언어": "locale", "language": "locale",
}

// importHeaderScanLimit bounds how far down a sheet the header row is looked
// for, so a title line or two above the table does not reject the whole file.
const importHeaderScanLimit = 10

// importHeaders reads one row as the header line and returns the column index
// of every recognised field.
func importHeaders(row []string) map[string]int {
	headers := map[string]int{}
	for index, raw := range row {
		key := strings.TrimPrefix(strings.TrimSpace(raw), "\ufeff")
		key = strings.ToLower(strings.NewReplacer(" ", "", "_", "", "-", "").Replace(key))
		if canonical := importHeaderAliases[key]; canonical != "" {
			headers[canonical] = index
		}
	}
	return headers
}

// importHeaderRow finds the row that carries both required columns. Sheets
// exported from a shared template often start with a title or a blank line, so
// the first row is not always the header. When no row within the scan limit
// qualifies the first row is returned so the caller reports which column is
// missing from it.
func importHeaderRow(rows [][]string) (int, map[string]int) {
	for index, row := range rows {
		if index >= importHeaderScanLimit {
			break
		}
		headers := importHeaders(row)
		if _, hasName := headers["name"]; !hasName {
			continue
		}
		if _, hasPhone := headers["phone"]; !hasPhone {
			continue
		}
		return index, headers
	}
	return 0, importHeaders(rows[0])
}

// importConsent reads the consent column the way people fill it in: an English
// yes, a Korean 예/동의, or the O/V/✓ marks Excel users put in a check column.
func importConsent(value string) bool {
	value = strings.ToLower(strings.TrimSpace(value))
	value = strings.TrimRight(value, ".!。")
	switch value {
	case "y", "yes", "true", "t", "1", "o", "ok", "v", "✓", "✔", "☑", "○", "◯", "ㅇ",
		"동의", "동의함", "동의합니다", "동의완료", "예", "네", "확인", "완료", "체크", "있음", "함", "수집동의", "개인정보동의":
		return true
	}
	return false
}

// importScientific matches the scientific notation Excel gives a numeric cell
// under a "0.00E+00" style format: a mantissa with an optional fraction and an
// exponent.
var importScientific = regexp.MustCompile(`^(\d+)(?:\.(\d+))?[eE]([+-]?\d+)$`)

// importPhone repairs a phone cell that Excel stored as a number. A number cell
// loses its leading 0 (01012345678 becomes 1012345678, which passes the length
// check and would be saved as a wrong number), and a scientific format renders
// it as 1.012345678E+09. Only 8–10 digit values without a leading 0 are
// prefixed, so an international number (821012345678) or a short extension is
// left alone; a value that already looks like a phone number is returned byte
// for byte. Scientific notation is expanded only when the mantissa carries every
// digit of the integer — a truncated 1.01E+09 would otherwise be saved as
// 01010000000, so it is left as is and falls through to the existing warning.
func importPhone(value string) string {
	if match := importScientific.FindStringSubmatch(value); match != nil {
		parsed, err := strconv.ParseFloat(value, 64)
		if err != nil || parsed <= 0 || parsed >= 1e15 || parsed != math.Trunc(parsed) {
			return value
		}
		integer := strconv.FormatInt(int64(parsed), 10)
		mantissa := strings.TrimLeft(match[1]+match[2], "0")
		if len(mantissa) < len(integer) {
			return value
		}
		value = integer
	}
	if len(value) < 8 || len(value) > 10 || value[0] == '0' {
		return value
	}
	for _, r := range value {
		if r < '0' || r > '9' {
			return value
		}
	}
	return "0" + value
}

func visitorInputsFromRows(rows [][]string) ([]VisitorInput, []string, error) {
	if len(rows) < 2 {
		return nil, nil, errors.New("헤더와 방문자 데이터가 필요합니다")
	}
	headerRow, headers := importHeaderRow(rows)
	if _, ok := headers["name"]; !ok {
		return nil, nil, errors.New("이름(name) 열이 필요합니다")
	}
	if _, ok := headers["phone"]; !ok {
		return nil, nil, errors.New("휴대전화(phone) 열이 필요합니다")
	}
	if len(rows) <= headerRow+1 {
		return nil, nil, errors.New("헤더와 방문자 데이터가 필요합니다")
	}
	// Warnings quote the row number the requester sees in Excel: the header is
	// row headerRow+1 and the first visitor is the row after it.
	rowNumber := func(rowIndex int) string { return strconv.Itoa(headerRow + rowIndex + 2) }
	cell := func(row []string, key string) string {
		index, ok := headers[key]
		if !ok || index >= len(row) {
			return ""
		}
		return strings.TrimSpace(row[index])
	}
	visitors := make([]VisitorInput, 0, len(rows)-headerRow-1)
	warnings := []string{}
	for rowIndex, row := range rows[headerRow+1:] {
		name, phone := cell(row, "name"), importPhone(cell(row, "phone"))
		if name == "" && phone == "" {
			continue
		}
		if len(visitors) >= 100 {
			return nil, nil, errors.New("한 번에 최대 100명의 방문자를 가져올 수 있습니다")
		}
		consent := importConsent(cell(row, "consent"))
		if name == "" || len(normalizePhone(phone)) < 7 {
			warnings = append(warnings, "행 "+rowNumber(rowIndex)+": 이름 또는 휴대전화를 확인하세요")
		}
		if !consent {
			warnings = append(warnings, "행 "+rowNumber(rowIndex)+": 개인정보 동의 확인이 필요합니다")
		}
		equipmentText := cell(row, "equipment")
		equipment := []string{}
		for _, item := range strings.FieldsFunc(equipmentText, func(r rune) bool { return r == ',' || r == ';' || r == '|' }) {
			if item = strings.TrimSpace(item); item != "" {
				equipment = append(equipment, item)
			}
		}
		visitors = append(visitors, VisitorInput{Name: name, Phone: phone, Email: cell(row, "email"), Company: cell(row, "company"), Title: cell(row, "title"), Vehicle: cell(row, "vehicle"), Equipment: equipment, Locale: normalizeLocale(cell(row, "locale")), Consent: consent})
	}
	if len(visitors) == 0 {
		return nil, nil, errors.New("가져올 방문자 데이터가 없습니다")
	}
	return visitors, warnings, nil
}
package app

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"mime/multipart"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"

	"github.com/xuri/excelize/v2"
	"golang.org/x/text/encoding/korean"
)

func uploadImport(t *testing.T, env *testEnv, filename string, content []byte) *httptest.ResponseRecorder {
	t.Helper()
	var body bytes.Buffer
	writer := multipart.NewWriter(&body)
	part, err := writer.CreateFormFile("file", filename)
	if err != nil {
		t.Fatalf("form file: %v", err)
	}
	if _, err := part.Write(content); err != nil {
		t.Fatalf("write: %v", err)
	}
	if err := writer.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	request := httptest.NewRequest(http.MethodPost, "/api/v1/visits/import/preview", &body)
	request.Header.Set("Content-Type", writer.FormDataContentType())
	request.Header.Set("X-CSRF-Token", env.csrf)
	request.RemoteAddr = "10.0.0.1:5000"
	for _, cookie := range env.cookies {
		request.AddCookie(cookie)
	}
	response := httptest.NewRecorder()
	env.handler.ServeHTTP(response, request)
	return response
}

func importedVisitors(t *testing.T, response *httptest.ResponseRecorder) ([]map[string]any, []any) {
	t.Helper()
	if response.Code != http.StatusOK {
		t.Fatalf("import returned %d: %s", response.Code, response.Body.String())
	}
	var body struct {
		Visitors []map[string]any `json:"visitors"`
		Warnings []any            `json:"warnings"`
	}
	if err := json.Unmarshal(response.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode: %v", err)
	}
	return body.Visitors, body.Warnings
}

func TestVisitorImportAcceptsExcelExports(t *testing.T) {
	env := newTestEnv(t)
	header := "이름,휴대전화,회사명,반입장비,개인정보동의\n"
	rows := "홍길동,010-1234-5678,ABC테크,노트북;카메라,동의\n김철수,010-9876-5432,XYZ,,동의\n"

	// UTF-8 with the byte-order mark Excel writes for "CSV UTF-8".
	utf8CSV := append([]byte{0xEF, 0xBB, 0xBF}, []byte(header+rows)...)
	visitors, warnings := importedVisitors(t, uploadImport(t, env, "visitors.csv", utf8CSV))
	if len(visitors) != 2 || visitors[0]["name"] != "홍길동" || len(warnings) != 0 {
		t.Fatalf("UTF-8 import: %v / %v", visitors, warnings)
	}
	equipment, _ := visitors[0]["equipment"].([]any)
	if len(equipment) != 2 {
		t.Fatalf("equipment not split: %v", visitors[0]["equipment"])
	}

	// Korean Excel's default "CSV (쉼표로 분리)" is CP949, not UTF-8.
	cp949, err := korean.EUCKR.NewEncoder().Bytes([]byte(header + rows))
	if err != nil {
		t.Fatalf("encode cp949: %v", err)
	}
	visitors, _ = importedVisitors(t, uploadImport(t, env, "visitors.csv", cp949))
	if len(visitors) != 2 || visitors[0]["name"] != "홍길동" || visitors[0]["company"] != "ABC테크" {
		t.Fatalf("CP949 import: %v", visitors)
	}

	// XLSX straight from Excel. Rows 3 and 4 hold the phone as a number, which
	// is what Excel stores when the cell is typed without a leading apostrophe:
	// the leading 0 is gone, and a scientific number format turns it into
	// 1.012345678E+09. Both must come back as 01012345678 without a warning.
	book := excelize.NewFile()
	defer book.Close()
	sheet := book.GetSheetName(0)
	for index, row := range [][]string{
		{"이름", "휴대전화", "회사명", "개인정보동의"},
		{"이영희", "010-5555-6666", "델타", "동의"},
		{"박숫자", "", "델타", "동의"},
		{"최지수", "", "델타", "동의"},
	} {
		for column, value := range row {
			cell, _ := excelize.CoordinatesToCellName(column+1, index+1)
			_ = book.SetCellValue(sheet, cell, value)
		}
	}
	if err := book.SetCellValue(sheet, "B3", 1012345678); err != nil {
		t.Fatalf("numeric phone cell: %v", err)
	}
	scientific := "0.000000000E+00"
	style, err := book.NewStyle(&excelize.Style{CustomNumFmt: &scientific})
	if err != nil {
		t.Fatalf("scientific style: %v", err)
	}
	if err := book.SetCellValue(sheet, "B4", 1012345678); err != nil {
		t.Fatalf("numeric phone cell: %v", err)
	}
	if err := book.SetCellStyle(sheet, "B4", "B4", style); err != nil {
		t.Fatalf("scientific phone cell: %v", err)
	}
	var xlsx bytes.Buffer
	if err := book.Write(&xlsx); err != nil {
		t.Fatalf("write xlsx: %v", err)
	}
	visitors, warnings = importedVisitors(t, uploadImport(t, env, "visitors.xlsx", xlsx.Bytes()))
	if len(visitors) != 3 || visitors[0]["name"] != "이영희" || visitors[0]["phone"] != "010-5555-6666" {
		t.Fatalf("XLSX import: %v", visitors)
	}
	if visitors[1]["phone"] != "01012345678" || visitors[2]["phone"] != "01012345678" {
		t.Fatalf("numeric phone cells should be restored to 01012345678, got %v / %v", visitors[1]["phone"], visitors[2]["phone"])
	}
	if len(warnings) != 0 {
		t.Fatalf("restored phones must not warn, got %v", warnings)
	}

	// A missing consent column is a warning, not a rejection: the requester
	// still has to tick consent per visitor in the form.
	_, warnings = importedVisitors(t, uploadImport(t, env, "visitors.csv", []byte("이름,휴대전화\n박민수,010-1111-2222\n")))
	if len(warnings) != 1 {
		t.Fatalf("expected a consent warning, got %v", warnings)
	}

	// Rejections carry a message the requester can act on.
	for _, bad := range []struct{ name, content, expect string }{
		{"visitors.txt", "이름,휴대전화\n홍길동,01011112222\n", "지원 파일 형식"},
		{"visitors.csv", "회사명\nABC\n", "이름"},
		{"visitors.csv", "이름,휴대전화\n", "방문자 데이터"},
	} {
		response := uploadImport(t, env, bad.name, []byte(bad.content))
		if response.Code != http.StatusBadRequest || !strings.Contains(response.Body.String(), bad.expect) {
			t.Fatalf("%s returned %d: %s", bad.name, response.Code, response.Body.String())
		}
	}

	// No file at all is a request error, not a panic.
	var empty bytes.Buffer
	writer := multipart.NewWriter(&empty)
	_ = writer.Close()
	request := httptest.NewRequest(http.MethodPost, "/api/v1/visits/import/preview", &empty)
	request.Header.Set("Content-Type", writer.FormDataContentType())
	request.Header.Set("X-CSRF-Token", env.csrf)
	for _, cookie := range env.cookies {
		request.AddCookie(cookie)
	}
	response := httptest.NewRecorder()
	env.handler.ServeHTTP(response, request)
	if response.Code != http.StatusBadRequest {
		t.Fatalf("missing file returned %d", response.Code)
	}

	// The preview feeds straight into a visit request.
	visitors, _ = importedVisitors(t, uploadImport(t, env, "visitors.csv", utf8CSV))
	for _, visitor := range visitors {
		visitor["consent"] = true
	}
	created := env.json(http.MethodPost, "/api/v1/visits", visitBody(env.siteID(), map[string]any{"visitors": visitors}), http.StatusCreated)
	if fmt.Sprint(created["visitorCount"]) != "2" {
		t.Fatalf("imported visitors did not become a visit: %v", created)
	}
	var stored int
	if err := env.server.db.QueryRow(context.Background(), `SELECT count(*) FROM visitors WHERE company='ABC테크'`).Scan(&stored); err != nil || stored != 1 {
		t.Fatalf("company not stored as typed: %d %v", stored, err)
	}
}

func TestImportPhoneRestoresLeadingZeroFromNumericCells(t *testing.T) {
	for _, tc := range []struct{ in, want string }{
		// Excel stored the cell as a number and dropped the leading 0.
		{"1012345678", "01012345678"},
		{"3112345678", "03112345678"},
		{"21234567", "021234567"},
		// A scientific number format keeps every digit here, so it is restored.
		{"1.012345678E+09", "01012345678"},
		{"1.012345678e9", "01012345678"},
		{"1.012345678E9", "01012345678"},
		{"3.112345678E+09", "03112345678"},
		// Already a phone number as typed: untouched byte for byte.
		{"01012345678", "01012345678"},
		{"010-1234-5678", "010-1234-5678"},
		{"010 1234 5678", "010 1234 5678"},
		{"+82 10 1234 5678", "+82 10 1234 5678"},
		{"+821012345678", "+821012345678"},
		// Outside the 8-10 digit window: an international number without +, or
		// something too short to be a phone at all.
		{"21012345678", "21012345678"},
		{"821012345678", "821012345678"},
		{"2.1012345678E+10", "21012345678"},
		{"1234567", "1234567"},
		{"12", "12"},
		{"", ""},
		// A truncated mantissa cannot be restored: 1.01E+09 would become
		// 01010000000, a wrong number stored silently. Leave it for the warning.
		{"1.01E+09", "1.01E+09"},
		{"1.0123E+09", "1.0123E+09"},
		{"1.01234567E+09", "1.01234567E+09"},
		// Not an integer, or too large to be exact: untouched.
		{"1.0123456785E+09", "1.0123456785E+09"},
		{"1.012345678E+15", "1.012345678E+15"},
		{"1E+09", "1E+09"},
		{"abc", "abc"},
	} {
		if got := importPhone(tc.in); got != tc.want {
			t.Errorf("importPhone(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}

	// Through the parser: the numeric cell is stored restored and does not warn,
	// while other columns are untouched.
	visitors, warnings, err := visitorInputsFromRows([][]string{
		{"이름", "휴대전화", "회사명", "개인정보동의"},
		{"홍길동", "1012345678", "1012345678", "동의"},
		{"김철수", "1.012345678E+09", "ABC", "동의"},
		{"이영희", "1.01E+09", "ABC", "동의"},
	})
	if err != nil || len(visitors) != 3 {
		t.Fatalf("parse: %v %v", visitors, err)
	}
	if visitors[0].Phone != "01012345678" || visitors[1].Phone != "01012345678" || visitors[2].Phone != "1.01E+09" {
		t.Fatalf("phones: %q %q %q", visitors[0].Phone, visitors[1].Phone, visitors[2].Phone)
	}
	if visitors[0].Company != "1012345678" {
		t.Fatalf("company column must not be touched, got %q", visitors[0].Company)
	}
	if len(warnings) != 1 || !strings.HasPrefix(warnings[0], "행 4:") {
		t.Fatalf("only the truncated row should warn, got %v", warnings)
	}
}

func TestImportConsentReadsKoreanAndCheckMarks(t *testing.T) {
	for _, value := range []string{"y", "Yes", " TRUE ", "1", "O", "o", "ok", "V", "✓", "✔", "○", "ㅇ", "동의", "동의함", "동의합니다.", "예", "네", "확인", "완료", "체크", "있음"} {
		if !importConsent(value) {
			t.Errorf("%q should count as consent", value)
		}
	}
