	in.Purpose = strings.TrimSpace(in.Purpose)
	if in.SiteID == "" || in.Purpose == "" || len(in.Visitors) == 0 || len(in.Visitors) > 100 {
		return nil, visitError{400, "required_fields", "사업장, 방문 목적, 방문자 1~100명은 필수입니다"}
